tool.command:
@PREPARE_ENV@ @PREPARE_CORPUS@ @PREPARE_DICTIONARY@
## 3. Run Find OOVs ## Syntax: mfa find_oovs [OPTIONS] CORPUS_DIRECTORY DICTIONARY_PATH OUTPUT_DIRECTORY mfa find_oovs corpus_dir $dict_arg output_dir --job_name 'mfa_find_oovs_job' #if str($speaker_characters): --speaker_characters '$speaker_characters' #end if
## MFA writes dictionary-specific filenames, and omits them when there are no OOVs. && find output_dir -maxdepth 1 -type f -name 'oovs_found_*.txt' -exec cat {} + > '$oovs_found' && find output_dir -maxdepth 1 -type f -name 'oov_counts_*.txt' -exec cat {} + > '$oov_counts'
